//! The small routines that work something out and call nothing.
//!
//! 1403 of them, each a handful of statements with no call, no branch and no loop.
//! A routine of this shape is a piece of arithmetic given a name.
//!
//! What is recorded is what each reads, what kinds of operation it uses, how
//! many things it is given and whether it answers anything. The arithmetic
//! itself is deliberately **not** reproduced: the decompiler's rendering of an
//! expression is its own work, not the program's, and this crate does not carry
//! it. What is here is what can be said about these routines without it.
//!
//! Said together, three things stand out. Almost all of them work on what they
//! were handed rather than on anything shared — only 176 of the 1403 touch a global
//! at all. Most read a **field** rather than a plain value, so they work inside
//! an object rather than on numbers passed in. And a fair number pack two
//! halves into one word, which is what a program that stores a position as a
//! pair of short numbers in a single machine word has to keep doing.

// The addresses are written without separators so the port-mapping importer can
// match them against the recovered functions.
#![allow(clippy::unreadable_literal)]

/// A kind of operation a routine uses.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum Uses {
    /// Reading something as a wider or narrower kind.
    AChangeOfWidth,
    /// Asking which of two is the greater, or whether they are alike.
    AComparison,
    /// Moving bits up or down.
    AShift,
    /// Adding, taking away, multiplying or dividing.
    Arithmetic,
    /// Combining bits without arithmetic.
    Bits,
    /// Putting two halves into one word.
    Packing,
}

/// Something a routine reads.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum Reads {
    /// A place inside something passed in.
    AField,
    /// Something the whole program shares.
    AGlobal,
    /// A register the decompiler could not account for.
    AProcessorRegister,
    /// Something passed in.
    WhatItWasGiven,
}

/// One routine that works something out.
#[derive(Debug, Clone, Copy)]
pub struct Computation {
    /// Where it sits.
    pub routine: u32,
    /// What kinds of operation it uses.
    pub uses: &'static [Uses],
    /// What it reads.
    pub reads: &'static [Reads],
    /// Whether it answers anything.
    pub answers: bool,
    /// How many things it is given.
    pub arity: u8,
    /// How many statements it is.
    pub statements: u8,
}

