/// How many there are.
pub const COMPUTATION_COUNT: usize = 1403;

/// Implements part of the computation family.
///
/// What one routine does, if it is one of these.
#[must_use]
pub fn computation_at(routine: u32) -> Option<&'static Computation> {
    COMPUTATIONS
        .binary_search_by_key(&routine, |held| held.routine)
        .ok()
        .map(|at| &COMPUTATIONS[at])
}

/// Implements part of the computation family.
///
/// Every routine that uses one kind of operation.
#[must_use]
pub fn using(uses: Uses) -> Vec<&'static Computation> {
    COMPUTATIONS
        .iter()
        .filter(|held| held.uses.contains(&uses))
        .collect()
}

/// Implements part of the computation family.
///
/// Every routine that reads one kind of thing.
#[must_use]
pub fn reading(reads: Reads) -> Vec<&'static Computation> {
    COMPUTATIONS
        .iter()
        .filter(|held| held.reads.contains(&reads))
        .collect()
}

/// Implements part of the computation family.
///
/// The routines that touch nothing outside what they were given.
///
/// The great majority. A routine here can be moved anywhere and will answer the
/// same, which is what makes this the part of the program easiest to be sure
/// about.
#[must_use]
pub fn depend_on_nothing_shared() -> Vec<&'static Computation> {
    COMPUTATIONS
        .iter()
        .filter(|held| !held.reads.contains(&Reads::AGlobal))
        .collect()
}

/// Implements part of the computation family.
///
/// What kinds of operation are used, commonest first.
#[must_use]
pub fn operations() -> Vec<(Uses, usize)> {
    let mut counted: Vec<(Uses, usize)> = Vec::new();
    for held in COMPUTATIONS.iter().flat_map(|held| held.uses.iter()) {
        match counted.iter_mut().find(|(seen, _)| seen == held) {
            Some((_, times)) => *times += 1,
            None => counted.push((*held, 1)),
        }
    }
    counted.sort_by(|left, right| right.1.cmp(&left.1).then(left.0.cmp(&right.0)));
    counted
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_count_is_what_the_table_holds() {
        assert_eq!(COMPUTATIONS.len(), COMPUTATION_COUNT);
    }

    #[test]
    fn the_table_is_sorted_so_it_can_be_searched() {
        assert!(
            COMPUTATIONS
                .windows(2)
                .all(|pair| pair[0].routine < pair[1].routine)
        );
    }

    #[test]
    fn a_routine_can_be_found_by_its_address() {
        let known = COMPUTATIONS[0].routine;

        assert!(computation_at(known).is_some());
        assert!(computation_at(0).is_none());
    }

    #[test]
    fn none_of_them_is_long() {
        for held in &COMPUTATIONS {
            assert!(held.statements >= 1, "{:#010X}", held.routine);
            assert!(held.statements <= 6, "{:#010X}", held.routine);
        }
    }

    #[test]
    fn most_are_only_a_statement_or_two() {
        let short = COMPUTATIONS
            .iter()
            .filter(|held| held.statements <= 2)
            .count();

        assert!(short * 2 > COMPUTATIONS.len());
    }

    #[test]
    fn arithmetic_is_the_commonest_thing_they_do() {
        assert_eq!(operations()[0].0, Uses::Arithmetic);
    }

    #[test]
    fn and_it_is_commoner_than_everything_else_put_together() {
        let counted = operations();
        let rest: usize = counted.iter().skip(1).map(|(_, seen)| *seen).sum();

        assert!(counted[0].1 * 2 > rest, "{} against {rest}", counted[0].1);
    }

    #[test]
    fn almost_none_of_them_touches_anything_shared() {
        // A routine here can be moved anywhere and will answer the same.
        let their_own = depend_on_nothing_shared().len();

        assert!(their_own * 10 > COMPUTATIONS.len() * 8);
    }

    #[test]
    fn most_read_a_field_rather_than_a_plain_value() {
        // So they work inside an object rather than on numbers passed in.
        let fields = reading(Reads::AField).len();

        assert!(fields * 2 > COMPUTATIONS.len());
    }

    #[test]
    fn nearly_all_read_something_they_were_given() {
        let given = reading(Reads::WhatItWasGiven).len();

        assert!(given * 10 > COMPUTATIONS.len() * 8);
    }

    #[test]
    fn a_fair_number_pack_two_halves_into_one_word() {
        // What a program storing a position as a pair of short numbers in one
        // machine word has to keep doing.
        assert!(using(Uses::Packing).len() > 50);
    }

    #[test]
    fn about_half_of_them_answer_something() {
        let answering = COMPUTATIONS.iter().filter(|held| held.answers).count();

        assert!(answering * 3 > COMPUTATIONS.len());
        assert!(answering < COMPUTATIONS.len());
    }

    #[test]
    fn and_the_rest_write_somewhere_instead() {
        let silent = COMPUTATIONS.iter().filter(|held| !held.answers).count();

        assert!(silent > 0);
    }

    #[test]
    fn none_takes_an_unreasonable_number_of_things() {
        for held in &COMPUTATIONS {
            assert!(held.arity <= 9, "{:#010X}", held.routine);
        }
    }

    #[test]
    fn none_of_these_is_already_spoken_for_by_another_sweep() {
        for held in COMPUTATIONS.iter().take(200) {
            assert!(crate::frame_pads::pad_at(held.routine).is_none());
            assert!(crate::straight_line_routines::sequence_of(held.routine).is_none());
            assert!(crate::two_way_routines::choice_at(held.routine).is_none());
            assert!(crate::trivial_routines::trivial_at(held.routine).is_none());
        }
    }

    #[test]
    fn every_routine_is_listed_once() {
        let mut routines: Vec<u32> = COMPUTATIONS.iter().map(|held| held.routine).collect();
        let before = routines.len();
        routines.sort_unstable();
        routines.dedup();

        assert_eq!(routines.len(), before);
    }
}
